// You can use this step to execute a variety of server-side javascript tests including
// jasmine tests and custom assertions
//
//
// Pass or fail a step: Override the step outcome to pass or fail. This is ignored 
//                      by jasmine tests
//
//  - Return true from the main function body to pass the step
//  - Return false from the main function body to fail the step
//
//
// outputs:       Pre-defined Step config Output variables to set on this step during 
//                execution that are available to later steps
//
// steps(SYS_ID): A function to retrieve Output variable data from a step that executed
//                earlier in the test. The desired step's sys_id is required
//
// params:        The current test run data set's parameter data including both 
//                exclusive and shared parameters
//
//  Example:
//
//      // Test step 1 - add data
//      var gr = new GlideRecord('sc_task');
//      // If parameterized testing is enabled, parameters are stored in the params object
//      gr.setValue('short_description', params.u_my_short_description)
//      gr.setValue('caller', params.u_my_user.manager)
//      // this sample step's Step config has Output variables named table and record_id
//      outputs.table = 'sc_task';
//      outputs.record_id = gr.insert();
//
//      // Test step 2 - access added data and validate
//      // check that the record exists (or that business logic changed it)
//      var gr = new GlideRecord("sc_task");
//      gr.get(steps(PREVIOUS_STEP_SYS_ID).record_id);
//      assertEqual({name: "task gr exists", shouldbe: true, value: gr.isValidRecord()});
//
//
// stepResult.setOutputMessage: Log a message to step results after step executes.
//                              Can only be called once or will overwrite previous 
//                              message
//
//  Example:
//
//      var gr = new GlideRecord('sc_task');
//      gr.setValue('short_description', 'verify task can be inserted');
//      var grSysId = gr.insert();
//      var justCreatedGR = new GlideRecord('sc_task');
//      if (justCreatedGR.get(grSysId)) {
//            stepResult.setOutputMessage("Successfully inserted task record");
//            return true; // pass the step
//      } else { 
//            stepResult.setOutputMessage("Failed to insert task record");
//            return false; // fail the step
//      }
//
//
// Note: describe is only supported in Global scope.
// Use 'describe' to create a suite of test scripts and 'it' to define test expectations
//
//  Example jasmine test:
//
//      describe('my suite of script tests', function() {
//            it('should meet expectations', function() {
//                  expect(true).not.toBe(false);
//            });
//      });
//      // make sure to uncomment jasmine.getEnv().execute(); outside the function body
//
//
// assertEqual: A function used to compare that assertion.shouldbe == assertion.value;
//              in case of failure it throws an Error and logs that the assertion by
//              name has failed
//
//  Example:
//
//      var testAssertion = {
//            name: "my test assertion",
//            shouldbe: "expected value"
//            value: "actual value",
//      };
//      assertEqual(testAssertion); // throws Error, logs message to test step output
//
(function(outputs, steps, params, stepResult, assertEqual) {
	var ohsmUtils = new x_hccc_hoc_ohs.HoCOHSMUtils();
	var INPUT_TEXT = {
		WIDTH50_NO_SPACE: 'WWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWW',
		WIDTH100_NO_SPACE: 'WWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWW',
		WIDTH50: 'WWWWW WWWWWWW WWWWWWWWWW WWWWWWW WWW WWWWWWWW WWWW',
		WIDTH100: 'WWWWW WWWWWWW WWWWWWWWWW WWWWWWW WWW WWWWWWWW WWWWWWWWW WWWWWWW WWWWWWWWWW WWWWWWW WWW WWWWWWWW WWWW',
		WIDTH445: 'Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua. Ut enim ad minim veniam, quis nostrud exercitation ullamco laboris nisi ut aliquip ex ea commodo consequat. Duis aute irure dolor in reprehenderit in voluptate velit esse cillum dolore eu fugiat nulla pariatur. Excepteur sint occaecat cupidatat non proident, sunt in culpa qui officia deserunt mollit anim id est laborum.'
	};

	describe('Passing 100 char line without space', function(){
		var line = INPUT_TEXT.WIDTH100_NO_SPACE;
		it('should return 1 line when the width is 100', function(){
			var res = ohsmUtils.getLinesInLine(line, 100);
			expect(res.length).toBe(1);
			expect(res[0]).toEqual(line);
		});
		it('should return 2 lines when the width is 99', function(){
			var res = ohsmUtils.getLinesInLine(line, 99);
			expect(res.length).toBe(2);
			expect(res[0].length).toEqual(99);
			expect(res[1].length).toEqual(1);
		});
		it('should return 10 lines when the width is 10', function(){
			var res = ohsmUtils.getLinesInLine(line, 10);
			expect(res.length).toBe(10);
			expect(res[0].length).toEqual(10);
			expect(res[1].length).toEqual(10);
			expect(res[2].length).toEqual(10);
			expect(res[3].length).toEqual(10);
			expect(res[4].length).toEqual(10);
			expect(res[5].length).toEqual(10);
			expect(res[6].length).toEqual(10);
			expect(res[7].length).toEqual(10);
			expect(res[8].length).toEqual(10);
			expect(res[9].length).toEqual(10);
		});
	});
	describe('Passing 100 char line with spaces', function(){
		var line = INPUT_TEXT.WIDTH100;
		it('should return 1 line when the width is 100', function(){
			var res = ohsmUtils.getLinesInLine(line, 100);
			expect(res.length).toBe(1);
			expect(res[0]).toEqual(line);
		});
		it('should return 2 lines when the width is 99', function(){
			var res = ohsmUtils.getLinesInLine(line, 99);
			var firstCharAfterLastSpaceIndex = line.lastIndexOf(' ', line.length) +1;
			expect(res.length).toBe(2);
			expect(res[0]).toEqual(line.substring(0, firstCharAfterLastSpaceIndex));
			expect(res[1]).toEqual(line.substring(firstCharAfterLastSpaceIndex));
		});
		it('should return more than 10 lines when the width is 10', function(){
			/*
			WWWWW 
			WWWWWWW 
			WWWWWWWWWW 
			WWWWWWW 
			WWW 
			WWWWWWWW 
			WWWWWWWWW 
			WWWWWWW 
			WWWWWWWWWW 
			WWWWWWW 
			WWW 
			WWWWWWWW 
			WWWW
			*/
			var res = ohsmUtils.getLinesInLine(line, 10);
			var expected = line.split(' ');
			expect(res.length).toBe(13);
			expect(res.length).toBe(expected.length);
			expect(res[0]).toEqual(expected[0]+' ');
			expect(res[1]).toEqual(expected[1]+' ');
			expect(res[2]).toEqual(expected[2]+' ');
			expect(res[3]).toEqual(expected[3]+' ');
			expect(res[4]).toEqual(expected[4]+' ');
			expect(res[5]).toEqual(expected[5]+' ');
			expect(res[6]).toEqual(expected[6]+' ');
			expect(res[7]).toEqual(expected[7]+' ');
			expect(res[8]).toEqual(expected[8]+' ');
			expect(res[9]).toEqual(expected[9]+' ');
			expect(res[10]).toEqual(expected[10]+' ');
			expect(res[11]).toEqual(expected[11]+' ');
			expect(res[12]).toEqual(expected[12]);
		});
	});
})(outputs, steps, params, stepResult, assertEqual);
jasmine.getEnv().execute();
